const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centerPoint = ee.Geometry.Point(-125.410394, -41.729403);
  const bufferRadiusKm = 100;
  const region = centerPoint.buffer(bufferRadiusKm * 1000); // Buffer in meters

  // Define comparison periods
  const startDate1 = '2018-11-01';
  const endDate1 = '2019-02-28'; // Prior year: Nov 2018 - Feb 2019

  const startDate2 = '2019-11-01';
  const endDate2 = '2020-02-29'; // Target year: Nov 2019 - Feb 2020 (Feb 29 for leap year)

  const modisCollectionId = 'MODIS/051/MOLT/L3_OC'; // MODIS Aqua Ocean Color, L3 monthly composites
  const bandName = 'chlor_a'; // Chlorophyll-a concentration

  const scale = 3000; // Use a reasonable scale to avoid timeouts for a 100km radius
  const maxPixels = 1e9;

  // 2. Data Acquisition & Check
  const getMeanChlorophyll = (startDate, endDate, periodName) => {
    const collection = ee.ImageCollection(modisCollectionId)
      .filterDate(startDate, endDate)
      .filterBounds(region);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${periodName} (${startDate} to ${endDate}).`);
      return { mean_value: null, pixel_count: 0 };
    }

    // Mosaic and reduce to get a single image representing the mean over the period
    const meanImage = collection.select(bandName).mean();

    // Calculate valid pixel count
    const pixelCountResult = meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    }).get(bandName);

    const pixelCount = pixelCountResult.getInfo();

    if (pixelCount === 0 || pixelCount === null) {
      console.log(`No valid pixels found for ${periodName} after processing.`);
      return { mean_value: null, pixel_count: 0 };
    }

    // Calculate mean chlorophyll concentration for the region
    const meanValueResult = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    }).get(bandName);

    const meanValue = meanValueResult.getInfo();

    return { mean_value: meanValue, pixel_count: pixelCount };
  };

  console.log('--- Processing Period 1 (Nov 2018 - Feb 2019) ---');
  const result1 = getMeanChlorophyll(startDate1, endDate1, 'Period 1');
  const meanChlor_2018_2019 = result1.mean_value;
  const pixels1 = result1.pixel_count;
  console.log(`2018-2019 Chlorophyll-a Mean: ${meanChlor_2018_2019 !== null ? meanChlor_2018_2019.toFixed(4) : 'N/A'} (Pixels: ${pixels1})`);

  console.log('--- Processing Period 2 (Nov 2019 - Feb 2020) ---');
  const result2 = getMeanChlorophyll(startDate2, endDate2, 'Period 2');
  const meanChlor_2019_2020 = result2.mean_value;
  const pixels2 = result2.pixel_count;
  console.log(`2019-2020 Chlorophyll-a Mean: ${meanChlor_2019_2020 !== null ? meanChlor_2019_2020.toFixed(4) : 'N/A'} (Pixels: ${pixels2})`);

  // 3. Validation & Final Answer
  if (pixels1 === 0 || pixels2 === 0) {
    if (pixels1 === 0 && pixels2 === 0) {
      console.log('C1: Empty Collection or C2: No Valid Pixels for both periods.');
    } else if (pixels1 === 0) {
      console.log('C1: Empty Collection or C2: No Valid Pixels for the prior year period.');
    } else {
      console.log('C1: Empty Collection or C2: No Valid Pixels for the target year period.');
    }
    console.log('C2'); // Combined C1/C2 because getMeanChlorophyll handles both for pixel count
    return;
  }

  if (meanChlor_2018_2019 === null || isNaN(meanChlor_2018_2019) ||
      meanChlor_2019_2020 === null || isNaN(meanChlor_2019_2020)) {
    console.log('C3'); // Calculation resulted in None or NaN
    return;
  }

  console.log(`Comparison: 2019-2020 (${meanChlor_2019_2020.toFixed(4)}) vs 2018-2019 (${meanChlor_2018_2019.toFixed(4)})`);

  if (meanChlor_2019_2020 > meanChlor_2018_2019) {
    console.log('A'); // Yes, chlorophyll concentrations were up
  } else {
    console.log('B'); // No, chlorophyll concentrations were not up
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
